import subprocess
import psutil
import time

def task_func(process_name: str) -> str:
    process_found = False

    for process in psutil.process_iter():
        try:
            if process.name() == process_name:
                process.terminate()
                process_found = True
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            continue

    subprocess.Popen(process_name)

    if process_found:
        return f"Process found. Restarting {process_name}."
    else:
        return f"Process not found. Starting {process_name}."

from flask import Flask, render_template, redirect, url_for
from flask_login import LoginManager, UserMixin, login_user, login_required, logout_user, current_user
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import DataRequired, Length
from werkzeug.security import generate_password_hash, check_password_hash

class LoginForm(FlaskForm):
    username = StringField('Username', validators=[DataRequired(), Length(min=4, max=25)])
    password = PasswordField('Password', validators=[DataRequired(), Length(min=8, max=80)])
    submit = SubmitField('Log In')

login_manager = LoginManager()

def task_func(secret_key, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    app.config['SECRET_KEY'] = secret_key

    login_manager.init_app(app)
    login_manager.login_view = 'login'

    class User(UserMixin):
        def __init__(self, id):
            self.id = id

    @login_manager.user_loader
    def load_user(user_id):
        return User(user_id)

    @app.route('/login', methods=['GET', 'POST'])
    def login():
        form = LoginForm()
        if form.validate_on_submit():
            user = User(form.username.data)
            login_user(user)
            return redirect(url_for('protected'))
        return render_template('login.html', form=form)

    @app.route('/logout')
    @login_required
    def logout():
        logout_user()
        return redirect(url_for('login'))

    @app.route('/protected')
    @login_required
    def protected():
        return f'Logged in as: {current_user.id}'

    return app

import pandas as pd
import matplotlib.pyplot as plt
from statsmodels.tsa.seasonal import seasonal_decompose

def task_func(df, freq='D', decomposition_model='multiplicative'):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("Input 'df' must be a pandas DataFrame.")

    if 'value' not in df.columns or 'date' not in df.columns:
        raise ValueError("DataFrame lacks required columns ('value', 'date').")

    if decomposition_model not in ['additive', 'multiplicative']:
        raise ValueError("Invalid decomposition_model. Must be 'additive' or 'multiplicative'.")

    try:
        offset = pd.tseries.frequencies.to_offset(freq)
        if offset is None:
            raise ValueError
    except Exception:
        raise ValueError(f"Invalid frequency string: {freq}")

    if df['value'].isnull().any():
        raise ValueError("Missing values found in the 'value' column.")

    if not pd.api.types.is_numeric_dtype(df['value']):
        raise ValueError("The 'value' column must contain numeric data.")

    ts = df.set_index('date')['value']
    ts.index = pd.to_datetime(ts.index)

    try:
        ts = ts.asfreq(freq)
    except Exception as e:
        raise ValueError(f"Error applying frequency '{freq}': {e}")

    if ts.isnull().any():
        raise ValueError("Resampling with the provided frequency introduced missing values.")

    try:
        result = seasonal_decompose(ts, model=decomposition_model)
    except ValueError as e:
        # e.g., Insufficient data points
        raise ValueError(str(e))

    fig = result.plot()
    axes = fig.axes

    return result, axes

import socket
from ipaddress import IPv4Network
from threading import Thread

def task_func(ip_range, port):
    results = {}
    threads = []

    def check_port(ip_str, port_num):
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(1.0)
        try:
            s.connect((ip_str, port_num))
            results[ip_str] = True
        except Exception:
            results[ip_str] = False
        finally:
            try:
                s.close()
            except Exception:
                pass

    # Iterating directly over IPv4Network yields all IPs in the range, 
    # including the network and broadcast addresses.
    for ip in IPv4Network(ip_range, strict=False):
        ip_str = str(ip)
        t = Thread(target=check_port, args=(ip_str, port))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    return results
